fn check_status(sat: String) -> &'static str {
    if sat.is_empty() { "unknown" } else { "ok" }
}

fn log_contact(sat: String) {
    sat.push_str(" (contacted)");
}

fn main() {
    let sat_a = String::from("sat-a");
    println!("{sat_a}: {}", check_status(sat_a));
    println!("{sat_a}: {}", check_status(sat_a));
    log_contact(sat_a);
    println!("{sat_a}");
}

fn add_bonus(score: &mut u32, bonus: u32) {
    *score += bonus; // change the value the reference points to
}

fn main() {
    let mut score = 40;
    add_bonus(&mut score, 2);
    let r = &score;
    let doubled = *r * 2;
    println!("{score} {doubled}");
}

